  accessible: { pos: "adj.", zh: "可取得的；容易接近的", level: 2, ex: "The internet made information accessible to everyone.", exZh: "網路讓每個人都能取得資訊。" },
  literacy: { pos: "n.", zh: "識字能力；讀寫能力", level: 2, ex: "Literacy rates have risen around the world.", exZh: "全球的識字率都在上升。" },
  entangle: { pos: "v.", zh: "纏住；使捲入", level: 3, ex: "The whale became entangled in a fishing net.", exZh: "那頭鯨魚被漁網纏住了。" },
