  omission: { pos: "n.", zh: "遺漏；省略", level: 3, ex: "The omission of her name from the list was a mistake.", exZh: "名單上漏掉她的名字是個錯誤。" },
  deplorable: { pos: "adj.", zh: "可悲的；糟糕透頂的", level: 3, ex: "The living conditions in the old prison were deplorable.", exZh: "舊監獄的生活條件糟糕透頂。" },
  alleviate: { pos: "v.", zh: "減輕；緩和", level: 3, ex: "This medicine will alleviate the pain.", exZh: "這個藥能減輕疼痛。" },
