  sinecure: { pos: "n.", zh: "閒差；領乾薪的職位", level: 3, ex: "His job at his uncle's company is a sinecure; he barely works.", exZh: "他在叔叔公司的工作是個閒差；他幾乎不用做事。" },
  feeble: { pos: "adj.", zh: "虛弱的；無力的", level: 2, ex: "The old flashlight gave off only a feeble light.", exZh: "那支舊手電筒只發出微弱的光。" },
  complicity: { pos: "n.", zh: "同謀；共犯關聯", level: 3, ex: "The driver denied any complicity in the robbery.", exZh: "那名司機否認參與了那起搶案。" },
  durable: { pos: "adj.", zh: "經久耐用的", level: 2, ex: "These hiking boots are durable enough to last for years.", exZh: "這雙登山靴很耐穿，可以穿很多年。" },
  liquidation: { pos: "n.", zh: "清理；消滅；清算", level: 3, ex: "The failing store is selling everything in a liquidation sale.", exZh: "那家經營不善的店正在清倉拍賣所有商品。" },
  tenacious: { pos: "adj.", zh: "堅韌的；頑強的", level: 2, ex: "The tenacious reporter kept asking until she got an answer.", exZh: "那位不屈不撓的記者一直追問，直到得到答案。" },
  accomplice: { pos: "n.", zh: "共犯；同謀", level: 3, ex: "Police arrested the thief and his accomplice.", exZh: "警方逮捕了小偷和他的共犯。" },
  tenacity: { pos: "n.", zh: "不屈不撓；韌性", level: 2, ex: "Learning a language takes tenacity and patience.", exZh: "學一門語言需要毅力和耐心。" },
  recant: { pos: "v.", zh: "撤回；撤回聲明自白", level: 3, ex: "The witness later recanted her statement.", exZh: "那位證人後來撤回了她的證詞。" },
  depiction: { pos: "n.", zh: "描繪；敘述", level: 2, ex: "The movie's depiction of city life feels very real.", exZh: "這部電影對城市生活的描繪感覺很真實。" },
  culpable: { pos: "adj.", zh: "應受歸咎的；有罪的", level: 3, ex: "The court found the company culpable for the pollution.", exZh: "法院判定那家公司應為污染負責。" },
  estheticism: { pos: "n.", zh: "唯美主義；美學主義", level: 3, ex: "The artist's estheticism made him care about beauty more than meaning.", exZh: "那位藝術家的唯美主義讓他重視美感勝過意義。" },
  abrogate: { pos: "v.", zh: "廢除；取消", level: 3, ex: "The new government abrogated the old trade agreement.", exZh: "新政府廢除了舊的貿易協定。" },
  perspective: { pos: "n.", zh: "透視法；觀點", level: 2, ex: "Traveling abroad gave me a new perspective on my own culture.", exZh: "出國旅行讓我對自己的文化有了新的觀點。" },
