  ambiguity: { pos: "n.", zh: "模稜兩可", level: 2, ex: "The ambiguity of the question confused many students.", exZh: "題目的模稜兩可讓很多學生感到困惑。" },
  access: { pos: "n.", zh: "進入管道；接觸機會", level: 1, ex: "All students have free access to the online library.", exZh: "所有學生都能免費使用線上圖書館。" },
  connotation: { pos: "n.", zh: "言外之意；隱含意義", level: 2, ex: "The word \"cheap\" often has a negative connotation.", exZh: "「cheap」這個字常常帶有負面的言外之意。" },
  invalidate: { pos: "v.", zh: "使作廢；使無效", level: 3, ex: "A missing signature can invalidate the whole contract.", exZh: "少一個簽名就可能讓整份合約無效。" },
  denote: { pos: "v.", zh: "表示；代表", level: 2, ex: "A red dot on the map denotes a hospital.", exZh: "地圖上的紅點代表醫院。" },
