  foresight: { pos: "n.", zh: "遠見；先見之明", level: 2, ex: "She had the foresight to bring an umbrella.", exZh: "她很有先見之明地帶了傘。" },
  fetter: { pos: "v./n.", zh: "束縛；桎梏；腳鐐", level: 3, ex: "He felt fettered by all the rules at his old job.", exZh: "他覺得在舊工作中被各種規定束縛住了。" },
