  persevere: { pos: "v.", zh: "堅毅不拔；堅持", level: 3, ex: "If you persevere, your English will keep improving.", exZh: "只要你堅持下去，英文就會持續進步。" },
  apathetic: { pos: "adj.", zh: "冷漠無感的", level: 2, ex: "Many young voters feel apathetic about politics.", exZh: "許多年輕選民對政治冷漠無感。" },
  paragon: { pos: "n.", zh: "模範；典範", level: 3, ex: "My grandmother was a paragon of patience.", exZh: "我祖母是耐心的典範。" },
  awareness: { pos: "n.", zh: "察覺；意識", level: 2, ex: "The campaign raised awareness of ocean pollution.", exZh: "這個活動提高了大眾對海洋污染的意識。" },
  nomadic: { pos: "adj.", zh: "遊牧的；流浪的", level: 3, ex: "Some nomadic tribes move with their animals every season.", exZh: "有些遊牧民族每個季節都帶著牲畜遷移。" },
