  array: { pos: "n.", zh: "一大批；一系列展示", level: 3, ex: "The store offers a wide array of teas from around the world.", exZh: "那家店提供來自世界各地的各式各樣茶葉。" },
  gap: { pos: "n.", zh: "差距；分歧；缺口", level: 1, ex: "There's a big gap between what he says and what he does.", exZh: "他說的和做的之間有很大的差距。" },
  obscure: { pos: "adj.", zh: "晦暗的；不知名的", level: 3, ex: "The song was written by an obscure band from the 1970s.", exZh: "這首歌是一個 1970 年代不知名的樂團寫的。" },
  retrieve: { pos: "v.", zh: "檢索；取回", level: 2, ex: "The dog retrieved the ball from the lake.", exZh: "狗把球從湖裡叼回來。" },
  ardent: { pos: "adj.", zh: "熱烈狂熱的", level: 3, ex: "He is an ardent fan of the local baseball team.", exZh: "他是本地棒球隊的狂熱球迷。" },
