  adamant: { pos: "adj.", zh: "堅決固執的", level: 3, ex: "She was adamant that she had locked the door.", exZh: "她堅稱自己有鎖門。" },
  elephantine: { pos: "adj.", zh: "龐大的；如象般的", level: 2, ex: "The elephantine truck could barely fit through the narrow street.", exZh: "那輛龐大的卡車勉強才擠過狹窄的街道。" },
